package br.com.onda;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class RadioStationTest {
 @Test public void directoryKeepsHttpsFallbacksAndAudioMetadata()throws Exception{String raw="[{\"stationuuid\":\"a\",\"name\":\"Rádio Antena\",\"url_resolved\":\"https://stream.example.org/live?token=a%2Bb\",\"country\":\"Brazil\",\"codec\":\"AAC+\",\"bitrate\":64},{\"stationuuid\":\"b\",\"name\":\"Reserva\",\"url_resolved\":\"http://old.example.org/radio\",\"url\":\"https://new.example.org/radio.m3u8\",\"hls\":1},{\"stationuuid\":\"x\",\"url_resolved\":\"http://example.org/live\"},{\"stationuuid\":\"a\",\"url_resolved\":\"https://duplicate.example.org/live\"}]";List<RadioStation> list=RadioStation.read(raw,true);assertEquals(2,list.size());assertEquals("Rádio Antena",list.get(0).name);assertEquals("https://stream.example.org/live?token=a%2Bb",list.get(0).url);assertTrue(list.get(0).detail().contains("AAC+"));assertTrue(list.get(1).hls);assertEquals("https://new.example.org/radio.m3u8",list.get(1).url);}
 @Test public void favoritesRoundTripAndManualIdsAreStable()throws Exception{RadioStation a=new RadioStation(null,"Minha rádio","https://audio.example.com:8443/listen?signature=abc%2B%3D","Brasil","MP3",128,false);RadioStation b=RadioStation.read(RadioStation.write(Arrays.asList(a)),false).get(0);assertEquals(a.id,b.id);assertEquals(a.url,b.url);assertEquals(a.name,b.name);assertNotEquals(a.id,RadioStation.key(a.url+"x"));}
 @Test public void localCredentialsAndInsecureLinksAreRejected(){for(String raw:new String[]{"http://radio.example.com/live","https://user:pass@radio.example.com/live","https://localhost/a","https://127.0.0.1/a","https://office.local/a","file:///radio.mp3","https://audio.example.com:70000/live","https://audio.example.com/live#x"})try{RadioStation.stream(raw);fail(raw);}catch(IllegalArgumentException expected){}}
 @Test public void namesKeepLettersAndHlsIsDetectedWithQuery(){RadioStation s=new RadioStation(null,"  Classic\tSports\nFM  ","https://audio.example.com/live.m3u8?token=abc%2B","Brasil","AAC",64,false);assertEquals("Classic Sports FM",s.name);assertTrue(s.hls);assertEquals("Brasil",s.country);}
}
